import qs4 from "qs";
var FileUtil = class {
  /**
   * 计算OSSCat参数
   *
   * @author zk
   * @date 2024-01-26 02:01:52
   * @param {string} url
   * @param {IContext} context
   * @return {*}  {string}
   * @memberof FileUtil
   */
  calcOSSCatUrl(url, context, OSSCatName) {
    var _a2;
    let uploadUrl = "".concat(ibiz.env.baseUrl, "/").concat(ibiz.env.appId).concat(url);
    const app = ibiz.hub.getApp(context.srfappid);
    const OSSCat = OSSCatName || app.model.defaultOSSCat || ((_a2 = app.model.userParam) == null ? void 0 : _a2.DefaultOSSCat);
    uploadUrl = uploadUrl.replace("/{cat}", OSSCat ? "/".concat(OSSCat) : "");
    return uploadUrl;
  }
  /**
   * 计算文件的上传路径和下载路径
   * 下载路径文件id用%fileId%占位，替换即可
   * 配置编辑器参数uploadParams和exportParams时，会像导航参数一样动态添加对应的参数到url上
   *
   * @author zk
   * @date 2024-01-26 02:01:15
   * @param {IData} data
   * @param {IContext} context
   * @param {IParams} params
   * @param {IParams} uploadParams
   * @param {IParams} exportParams
   * @return {*}  {{
   *     uploadUrl: string;
   *     downloadUrl: string;
   *   }}
   * @memberof FileUtil
   */
  calcFileUpDownUrl(context, params, data = {}, extraParams = {}) {
    const { uploadParams, exportParams, osscat: OSSCatName } = extraParams;
    let uploadUrl = this.calcOSSCatUrl(
      ibiz.env.uploadFileUrl,
      context,
      OSSCatName
    );
    let downloadUrl = this.calcOSSCatUrl(
      "".concat(ibiz.env.downloadFileUrl, "/%fileId%"),
      context,
      OSSCatName
    );
    let _uploadParams = {};
    let _exportParams = {};
    if (uploadParams) {
      _uploadParams = convertNavData(uploadParams, data, params, context);
    }
    if (exportParams) {
      _exportParams = convertNavData(exportParams, data, params, context);
    }
    uploadUrl += qs4.stringify(_uploadParams, { addQueryPrefix: true });
    downloadUrl += qs4.stringify(_exportParams, { addQueryPrefix: true });
    return { uploadUrl, downloadUrl };
  }
  /**
   * 请求url获取文件流，并用JS触发文件下载
   *
   * @author zk
   * @date 2024-01-26 02:01:29
   * @param {{ url: string; name: string }} file
   * @memberof FileUtil
   */
  async fileDownload(url, name2) {
    const response = await ibiz.net.request(url, {
      method: "get",
      responseType: "blob",
      baseURL: ""
      // 已经有baseURL了，这里无需再写
    });
    if (response.status !== 200) {
      throw new RuntimeError67(ibiz.i18n.t("runtime.platform.failedDownload"));
    }
    if (!response.data) {
      throw new RuntimeError67(ibiz.i18n.t("runtime.platform.fileStreamData"));
    } else {
      let fileName = ibiz.util.file.getFileName(response);
      if (name2)
        fileName = name2;
      downloadFileFromBlob2(response.data, fileName);
    }
  }
  /**
   * 文件上传
   *
   * @author zk
   * @date 2024-01-26 05:01:35
   * @param {string} uploadUrl
   * @param {Blob} file
   * @param {IData} headers
   * @return {*}  {Promise<IData>}
   * @memberof FileUtil
   */
  async fileUpload(uploadUrl, file, headers) {
    const formData = new FormData();
    formData.append("file", file);
    const res = await ibiz.net.axios({
      url: uploadUrl,
      method: "post",
      headers,
      data: formData
    });
    if (res.status !== 200) {
      throw new RuntimeError67(
        ibiz.i18n.t("runtime.utils.fileUtil.fileUploadFailed")
      );
    }
    return res.data;
  }
  /**
   * 获取文件名
   *
   * @param {IHttpResponse<IData>} response
   * @return {*}  {string}
   * @memberof FileUtil
   */
  getFileName(response) {
    let fileName = "";
    const contentDisposition = response.headers["content-disposition"];
    if (!contentDisposition) {
      return fileName;
    }
    const disposition = qs4.parse(contentDisposition, {
      delimiter: ";"
    });
    if (disposition && disposition.filename) {
      fileName = disposition.filename;
    }
    if (fileName.startsWith('"') && fileName.endsWith('"')) {
      fileName = fileName.substring(1, fileName.length - 1);
    }
    return fileName;
  }
  /**
   * 选择文件并上传
   *
   * @param {IContext} context
   * @param {IParams} params
   * @param {IData} data
   * @param {IData} [option={}]
   * @return {*}  {Promise<IData[]>}
   * @memberof FileUtil
   */
  async chooseFileAndUpload(context, params, data, option = {}) {
    const { accept, multiple, showUploadManager } = option;
    const urls = ibiz.util.file.calcFileUpDownUrl(context, params, data);
    const files = await ibiz.util.file.chooseFile(accept, multiple);
    let promises = [];
    const headers = {};
    const token = getAppCookie2(CoreConst3.TOKEN);
    if (token) {
      Object.assign(headers, {
        ["".concat(ibiz.env.tokenHeader, "Authorization")]: "".concat(ibiz.env.tokenPrefix, "Bearer ").concat(token)
      });
    }
    if (showUploadManager) {
      promises = await ibiz.notification.uploadManager({
        uploadUrl: urls.uploadUrl,
        files,
        headers
      });
      return promises;
    }
    for (let i = 0; i < files.length; i++) {
      const promise = await ibiz.util.file.fileUpload(
        urls.uploadUrl,
        files[i],
        headers
      );
      promises.push(promise);
    }
    return Promise.all(promises);
  }
  /**
   * 选择文件
   *
   * @param {string} [accept='']
   * @param {boolean} [multiple=false]
   * @return {*}  {Promise<FileList>}
   * @memberof FileUtil
   */
  chooseFile(accept = "", multiple = false) {
    return new Promise((resolve) => {
      const inputElement = document.createElement("input");
      inputElement.type = "file";
      inputElement.accept = accept;
      inputElement.multiple = multiple;
      inputElement.webkitdirectory = false;
      inputElement.addEventListener("change", (e) => {
        resolve(e.target.files);
      });
      document.body.appendChild(inputElement);
      inputElement.click();
      document.body.removeChild(inputElement);
    });
  }
};

// src/utils/short-cut/short-cut-util.ts
import { QXEvent as QXEvent9 } from "qx-util";
var ShortCutUtil = class {
  /**
   * Creates an instance of ShortCutUtil.
   * @memberof ShortCutUtil
   */
  constructor() {
    /**
     * 快捷方式
     *
     * @private
     * @type {IShortCut[]}
     * @memberof ShortCutUtil
     */
    this.$ShortCut = {
      items: [],
      mode: "vertical"
    };
    /**
     * 事件监听器
     *
     * @protected
     * @memberof ShortCutUtil
     */
    this.evt = new QXEvent9();
    this.initShortCut();
  }
  /**
   * 快捷方式数据
   *
   * @memberof ShortCutUtil
   */
  get data() {
    return this.$ShortCut.items;
  }
  /**
   * 快捷方式模式
   *
   * @readonly
   * @type {string}
   * @memberof ShortCutUtil
   */
  get mode() {
    return this.$ShortCut.mode;
  }
  /**
   * 初始化快捷方式数据
   *
   * @private
   * @memberof ShortCutUtil
   */
  initShortCut() {
    const shortcut = window.localStorage.getItem("IBizShortCut");
    if (shortcut) {
      this.$ShortCut = JSON.parse(shortcut);
    }
  }
  /**
   * 持久化保存快捷方式
   *
   * @memberof ShortCutUtil
   */
  saveShortCut() {
    this.evt.emit("change", [...this.$ShortCut.items]);
    window.localStorage.setItem("IBizShortCut", JSON.stringify(this.$ShortCut));
  }
  /**
   * 设置快捷方式模式
   *
   * @param {('horizontal' | 'vertical')} mode
   * @memberof ShortCutUtil
   */
  setShortCutMode(mode) {
    this.$ShortCut.mode = mode;
    window.localStorage.setItem("IBizShortCut", JSON.stringify(this.$ShortCut));
  }
  /**
   * 订阅数据改变事件
   *
   * @param {(data: IShortCutData) => void} callback 回调
   * @memberof ShortCutUtil
   */
  onChange(callback) {
    this.evt.on("change", callback);
  }
  /**
   * 取消订阅
   *
   * @param {(data: IShortCutData) => void} callback
   * @memberof ShortCutUtil
   */
  offChange(callback) {
    this.evt.off("change", callback);
  }
  /**
   * 计算快捷方式key
   *
   * @param {{
   *     context: IContext;
   *     appViewId: string;
   *   }} {
   *     context,
   *     appViewId,
   *   }
   * @return {*}  {Promise<string>}
   * @memberof ShortCutUtil
   */
  async calcShortCutKey({
    context,
    appViewId
  }) {
    const appView = await ibiz.hub.config.view.get(appViewId);
    let key = "".concat(context.srfappid, "-").concat(context.srfuserid, "-").concat(appViewId);
    if (appView.appDataEntityId) {
      const deName = calcDeCodeNameById(appView.appDataEntityId);
      key += "-".concat(deName, "-").concat(context[deName]);
    }
    return key;
  }
  /**
   * 添加快捷方式
   *
   * @param {IShortcut} shortcut
   * @memberof ShortCutUtil
   */
  addShortCut(shortCut) {
    const index = this.$ShortCut.items.findIndex(
      (item) => item.key === shortCut.key
    );
    if (index > -1) {
      this.$ShortCut.items.splice(index, 1, shortCut);
    } else {
      this.$ShortCut.items.push(shortCut);
    }
    this.saveShortCut();
  }
  /**
   * 删除快捷方式
   *
   * @param {string} key
   * @memberof ShortcutUtil
   */
  removeShortCut(key) {
    const index = this.$ShortCut.items.findIndex((item) => item.key === key);
    if (index > -1) {
      this.$ShortCut.items.splice(index, 1);
      this.saveShortCut();
    }
  }
  /**
   * 改变顺序
   *
   * @param {number} newIndex 新位置索引
   * @param {number} oldIndex 旧位置索引
   * @memberof ShortcutUtil
   */
  changeIndex(newIndex, oldIndex) {
    const { length } = this.$ShortCut.items;
    if (oldIndex < 0 || oldIndex >= length || newIndex < 0 || newIndex >= length) {
      throw new Error(
        ibiz.i18n.t("runtime.utils.shortCut.invalidIndexNewIndex", {
          newIndex,
          oldIndex,
          length
        })
      );
    }
    const removedItem = this.$ShortCut.items.splice(oldIndex, 1)[0];
    this.$ShortCut.items.splice(newIndex, 0, removedItem);
    this.saveShortCut();
  }
  /**
   * 是否存在最小化
   *
   * @param {string} key
   * @return {*}  {boolean}
   * @memberof ShortCutUtil
   */
  isExist(key) {
    const index = this.$ShortCut.items.findIndex((item) => item.key === key);
    if (index >= 0) {
      return true;
    }
    return false;
  }
};

